import React from 'react';
import { Navigate, useLocation } from 'react-router-dom';
import { useAppSelector } from '../../store/hooks';
import { UserRole } from '../../models/User';
import {
  getHomePath,
  isPathAllowed,
  hasValidAuthToken,
  usePermissionsReady,
  PermissionsBootstrapLoading,
} from '@linm-soft-org/linm-web-common-components';
import { isHomeDevAuthBypass } from '../../dev/isHomeDevAuthBypass';

interface ProtectedRouteProps {
  children: React.ReactNode;
  allowedRoles?: UserRole[];
}

/**
 * Protected route component that requires authentication.
 *
 * Guard order:
 *  1. Not authenticated → redirect to /login
 *  2. allowedRoles specified but user's role not included → redirect to /unauthorized
 *  3. Current path not covered by the user's menu → redirect to /unauthorized
 */
export const ProtectedRoute: React.FC<ProtectedRouteProps> = ({
  children,
  allowedRoles,
}) => {
  const { isAuthenticated, user } = useAppSelector((state) => state.auth);
  const location = useLocation();
  const permissionsReady = usePermissionsReady();
  const devBypass = isHomeDevAuthBypass();

  if (!devBypass && (!isAuthenticated || !hasValidAuthToken())) {
    return <Navigate to="/login" replace />;
  }

  if (!devBypass && !permissionsReady) {
    return <PermissionsBootstrapLoading />;
  }

  if (!devBypass && location.pathname === '/') {
    const homePath = getHomePath(
      user?.role,
      user?.package,
      user?.defaultMenuUrl,
      user?.packageDefaultUrl,
    );
    if (homePath !== '/') {
      return <Navigate to={homePath} replace />;
    }
  }

  if (allowedRoles && allowedRoles.length > 0 && user) {
    if (!allowedRoles.includes(user.role)) {
      return <Navigate to="/unauthorized" replace />;
    }
  }

  if (!devBypass && user && !isPathAllowed(user.role, user.package, location.pathname)) {
    return <Navigate to="/unauthorized" replace />;
  }

  return <>{children}</>;
};
