import { adminAccountsService, type AdminAccountListItem } from '../services/admin';

const PAGE_SIZE = 100;
const MAX_PAGES = 200;

/** Load all active accounts for a company (paginated API loop). */
export async function fetchAllCompanyAccounts(companyId: string): Promise<AdminAccountListItem[]> {
  const items: AdminAccountListItem[] = [];
  let page = 1;
  let total = 0;

  while (page <= MAX_PAGES) {
    const res = await adminAccountsService.getAccounts({
      companyId,
      status: 'Active',
      page,
      pageSize: PAGE_SIZE,
    });
    total = res.total ?? 0;
    items.push(...res.items);
    if (items.length >= total || res.items.length === 0) break;
    page += 1;
  }

  return items;
}
